8	 * The tools are driven through the real handler (RustCoreBridge.executeTool) with a manager whose server table points at
9	 * the fake, as cg3_diagnostics_evidence.test.ts does. Some cases wait for a fixed product timer (5000 ms initialize and
10	 * diagnostics timeouts, the 4000 ms grace period): those are the behaviour under test. No outcome depends on a race:
11	 * the fake only does what its scenario says, and anything "late" is released by the test, not by a clock.
12	 */
13	import "./helpers/leak_guard.js";
14	import { test } from "node:test";
15	import assert from "node:assert/strict";
16	import * as fs from "node:fs";
17	import * as os from "node:os";
18	import * as path from "node:path";
19	import { fileURLToPath, pathToFileURL } from "node:url";
20	import { LspBridgeManager, type LspClient } from "../src/lsp.js";
21	import { RustCoreBridge } from "../src/tools.js";
22	import { scanForInjection } from "../src/core/injection_scanner.js";
