26	/** The product's fixed timers (cli/src/lsp.ts): the initialize request, the manager's default diagnostics timeout, the no-progress grace period. */
27	const INITIALIZE_TIMEOUT_MS = 5000;
28	const DIAGNOSTICS_TIMEOUT_MS = 5000;
29	const GRACE_MS = 4000;
30	/**
31	 * Bounds for a wait that a product timer of `ms` ends. Lower: libuv arms a timer from its cached loop clock, which lags
32	 * the real clock by the time already spent in the current loop turn, so a timer can fire slightly early against
33	 * performance.now(); 50 ms covers only that. Upper: 2500 ms of room for a loaded host; it stays below the next product
34	 * constant an answer could be confused with (the 8000 ms request timeout and edit window).
35	 */
36	function assertEndedByTimer(elapsedMs: number, ms: number, what: string): void {
37	  assert.ok(elapsedMs >= ms - 50 && elapsedMs < ms + 2500, `${what}: took ${Math.round(elapsedMs)} ms, expected the ${ms} ms timer`);
38	}
