40	type Entry = { event: string; method?: string; id?: unknown; params?: any; docs?: Record<string, any>; to?: string; result?: unknown; error?: unknown; pid?: number; signal?: string };
41	
42	const diag = (severity: number | undefined, message: string) => ({
43	  range: { start: { line: 0, character: 0 }, end: { line: 0, character: 1 } },
44	  ...(severity === undefined ? {} : { severity }),
45	  message,
46	  source: "fake",
47	});
48	const publish = (diagnostics: unknown[], uri = "$uri", extra: Record<string, unknown> = {}) => ({ method: "textDocument/publishDiagnostics", params: { uri, diagnostics, ...extra } });
49	const progress = (kind: "begin" | "end") => ({ method: "$/progress", params: { token: "analysis", value: { kind } } });
50	
51	const alive = (pid: number): boolean => {
52	  try {
53	    process.kill(pid, 0);
54	    return true;
55	  } catch {
56	    return false;
57	  }
58	};
59	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
60	/** Waits (bounded) for something that is expected to happen; false if it did not. */
61	async function eventually(check: () => boolean, withinMs = 10_000): Promise<boolean> {
62	  for (const end = performance.now() + withinMs; performance.now() < end; await sleep(20)) if (check()) return true;
63	  return check();
64	}
