66	interface Opened {
67	  ws: string;
68	  mgr: LspBridgeManager;
69	  uri: (name: string) => string;
70	  tool: (name: string, args: Record<string, unknown>) => Promise<{ success: boolean; output: string; error?: string }>;
71	  client: () => Promise<LspClient>;
72	  /** One request round trip: when it returns, the fake has logged everything the client wrote before it. */
73	  sync: () => Promise<void>;
74	  log: () => Entry[];
75	  received: (method: string) => Entry[];
76	  /** Shuts everything down, asserts every process the fake logged (server, grandchild) is gone, removes the temp tree. */
77	  close: () => Promise<void>;
78	}
79	
80	function open(scenario: Record<string, unknown>, files: Record<string, string>, opts: { awaitProgress?: boolean; cmd?: string; viaSymlink?: boolean } = {}): Opened {
81	  const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "nexus-lsp-char-")));
82	  const real = path.join(root, "ws");
83	  fs.mkdirSync(real);
84	  for (const [name, text] of Object.entries(files)) fs.writeFileSync(path.join(real, name), text);
85	  let ws = real;
86	  if (opts.viaSymlink) {
87	    ws = path.join(root, "link");
88	    fs.symlinkSync(real, ws);
89	  }
90	  const logFile = path.join(root, "fake.log.jsonl");
91	  const scenarioFile = path.join(root, "scenario.json");
92	  fs.writeFileSync(scenarioFile, JSON.stringify({ ...scenario, log: logFile }));
93	  const mgr = new LspBridgeManager(ws, {
94	    servers: { ".ts": { cmd: opts.cmd ?? process.execPath, args: opts.cmd ? [] : [FAKE, scenarioFile], languageId: "typescript", awaitProgress: opts.awaitProgress === true } },
95	  });
96	  const bridge = new RustCoreBridge(ws);
97	  (bridge as any).lsp = mgr;
98	  const log = (): Entry[] => (fs.existsSync(logFile) ? fs.readFileSync(logFile, "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l)) : []);
99	  const client = async () => {
100	    const c = await mgr.getClientForFile("a.ts");
101	    assert.ok(c, "the fake server started");
102	    return c;
103	  };
104	  return {
105	    ws,
106	    mgr,
107	    uri: (name) => pathToFileURL(path.join(ws, name)).href,
108	    tool: (name, args) => bridge.executeTool(name, args),
109	    client,
110	    sync: async () => void (await (await client()).sendRequest("test/sync", {})),
111	    log,
112	    received: (method) => log().filter((e) => e.event === "recv" && e.method === method),
113	    close: async () => {
114	      bridge.shutdown();
115	      mgr.shutdownAll();
116	      const pids = log().filter((e) => e.event === "start" || e.event === "grandchild").map((e) => e.pid!);
117	      const gone = await eventually(() => pids.every((pid) => !alive(pid)));
118	      fs.rmSync(root, { recursive: true, force: true });
119	      assert.ok(gone, `a process started for this test is still running: ${pids.filter(alive).join(", ")}`);
120	    },
121	  };
122	}
123	
124	/** The records inside a fenced lsp_diagnostics result. */
125	function records(output: string): Array<Record<string, unknown>> {
126	  const lines = output.split("\n");
127	  assert.match(lines[0], /^\(untrusted tool output: lsp diagnostics for /);
128	  assert.equal(lines.at(-1), "(end untrusted tool output)");
129	  return JSON.parse(lines.slice(1, -1).join("\n"));
130	}
