1	// Real language servers (CS-6). The v1.2.0 LSP support (lsp.ts) is otherwise tested only against test/fixtures/fake_lsp_server.mjs.
2	// Here the product's own LspBridgeManager starts the real server, found the way the product finds it (the default
3	// extension -> command table, resolved on the scrubbed PATH buildLspEnvironment returns), on a tiny fixture project:
4	//   - a file with one deliberate error must yield status "ok" with an error diagnostic naming it;
5	//   - a clean file must yield status "ok" with an EMPTY list (a real report), which is not "unavailable";
6	//   - a manager whose server cannot start must yield "unavailable" (the contrast the two above are read against).
7	// A server that is not installed SKIPS with its reason, unless NEXUS_LSP_REQUIRE names it ("1" or "all" = every server,
8	// or a comma list such as "typescript,python"), in which case its absence is a failure. The scheduled workflow
9	// .github/workflows/lsp-real-servers.yml sets it. The availability probe runs with the SAME environment the product
10	// gives the server (buildLspEnvironment), so a tool visible only to the shell (a `pip install --user` under another HOME)
11	// is reported missing instead of passing the probe and failing later.
12	import { test } from "node:test";
13	import assert from "node:assert/strict";
14	import { spawnSync } from "node:child_process";
15	import * as fs from "node:fs";
16	import * as os from "node:os";
17	import * as path from "node:path";
18	import { LspBridgeManager, buildLspEnvironment } from "../src/lsp.js";
19	
20	interface Case {
21	  /** Why this case is not yet validated on a real run; it then reports as a todo unless NEXUS_LSP_REQUIRE names it. */
22	  unvalidated?: string;
23	  id: string;
24	  label: string;
25	  cmd: string;
26	  /** Run to prove the binary works (exit 0); null when the server has no such mode and the PATH lookup must do. */
27	  probe: string[] | null;
28	  files: Record<string, string>;
29	  bad: string;
30	  clean: string;
31	  /** A valid replacement for the deliberate error, used to exercise real didChange notifications. */
32	  fixed: string;
33	  /** Matches the message of the deliberate error. */
34	  message: RegExp;
35	  timeoutMs: number;
36	}
37	
38	const CASES: Case[] = [
39	  {
40	    id: "typescript",
41	    label: "typescript-language-server",
42	    cmd: "typescript-language-server",
43	    probe: ["--version"],
44	    files: {
45	      "tsconfig.json": JSON.stringify({ compilerOptions: { strict: true, noEmit: true, target: "es2022", module: "esnext" }, include: ["*.ts"] }),
46	      "bad.ts": 'export const n: number = "not a number";\n',
47	      "clean.ts": "export const ok: number = 1;\n",
48	    },
49	    bad: "bad.ts",
50	    clean: "clean.ts",
51	    fixed: 'export const n: number = 1;\n',
52	    message: /string.*not assignable.*number|not assignable/i,
53	    timeoutMs: 60_000,
54	  },
55	  {
56	    id: "python",
57	    label: "pyright-langserver",
58	    cmd: "pyright-langserver",
59	    probe: null,
60	    files: {
61	      "pyrightconfig.json": JSON.stringify({ typeCheckingMode: "basic" }),
62	      "bad.py": 'x: int = "not an int"\n',
63	      "clean.py": "x: int = 1\n",
64	    },
65	    bad: "bad.py",
66	    clean: "clean.py",
67	    fixed: "x: int = 1\n",
68	    message: /str.*not assignable.*int|not assignable/i,
69	    timeoutMs: 60_000,
70	  },
71	  {
72	    id: "rust",
73	    label: "rust-analyzer",
74	    cmd: "rust-analyzer",
75	    probe: ["--version"],
76	    files: {
77	      "Cargo.toml": '[package]\nname = "lspfixture"\nversion = "0.0.0"\nedition = "2021"\n',
78	      "src/main.rs": 'fn main() {\n    let x: i32 = "not an int";\n    let _ = x;\n}\n',
79	      "src/clean.rs": "pub fn ok() -> i32 {\n    1\n}\n",
80	    },
81	    bad: "src/main.rs",
82	    clean: "src/clean.rs",
83	    fixed: "fn main() {\n    let x: i32 = 1;\n    let _ = x;\n}\n",
84	    message: /mismatched types|expected i32/i,
85	    timeoutMs: 120_000,
86	  },
87	  {
88	    id: "go",
89	    label: "gopls",
90	    cmd: "gopls",
91	    probe: ["version"],
92	    files: {
93	      "go.mod": "module lspfixture\n\ngo 1.21\n",
94	      "bad.go": 'package main\n\nfunc main() {\n\tvar x int = "not an int"\n\t_ = x\n}\n',
95	      "clean.go": "package main\n\nfunc ok() int {\n\treturn 1\n}\n",
96	    },
97	    bad: "bad.go",
98	    clean: "clean.go",
99	    fixed: "package main\n\nfunc main() {\n\tvar x int = 1\n\t_ = x\n}\n",
100	    message: /cannot use|string.*int/i,
101	    timeoutMs: 90_000,
102	  },
103	];
104	
105	function required(id: string): boolean {
106	  const v = (process.env.NEXUS_LSP_REQUIRE ?? "").trim().toLowerCase();
107	  if (v === "") return false;
108	  if (v === "1" || v === "all" || v === "true") return true;
109	  return v.split(",").map((s) => s.trim()).includes(id);
110	}
111	
112	/** Where the product would find `cmd`: the first executable on the PATH it gives a language server for `workspace`. */
113	function resolveOnProductPath(cmd: string, workspace: string): { bin: string | null; env: Record<string, string> } {
114	  const env = buildLspEnvironment(workspace);
115	  for (const dir of (env.PATH ?? "").split(path.delimiter)) {
116	    const candidate = path.join(dir, cmd);
117	    try {
118	      fs.accessSync(candidate, fs.constants.X_OK);
119	      if (fs.statSync(candidate).isFile()) return { bin: candidate, env };
120	    } catch {
121	      /* next entry */
122	    }
123	  }
124	  return { bin: null, env };
125	}
126	
127	/** null when usable; otherwise the reason it is not. */
128	function unavailableReason(c: Case, workspace: string): string | null {
129	  const { bin, env } = resolveOnProductPath(c.cmd, workspace);
130	  if (!bin) return `${c.cmd} is not on the PATH the product gives a language server`;
131	  if (c.probe) {
132	    // In the fixture directory, as the product launches the server: a rustup proxy picks its toolchain from the working directory (a repo's rust-toolchain.toml would hide a missing default component).
133	    const r = spawnSync(bin, c.probe, { env, cwd: workspace, encoding: "utf-8", timeout: 20_000 });
134	    if (r.status !== 0) {
135	      const why = (r.stderr || r.error?.message || `exit ${r.status}`).toString().trim().split("\n")[0];
136	      return `${c.cmd} ${c.probe.join(" ")} failed under the product environment (${why})`;
137	    }
138	  }
139	  return null;
140	}
141	
142	function writeFixture(files: Record<string, string>): string {
143	  const dir = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "nexus-lsp-real-")));
144	  for (const [name, text] of Object.entries(files)) {
145	    fs.mkdirSync(path.dirname(path.join(dir, name)), { recursive: true });
146	    fs.writeFileSync(path.join(dir, name), text);
147	  }
148	  return dir;
149	}
150	
151	/** Larger than the three-file smoke fixture: 64 source files in one project, including the diagnostic target. */
152	function writeLargeFixture(c: Case): string {
153	  const files = { ...c.files };
154	  for (let i = 0; i < 62; i++) {
155	    const n = String(i).padStart(2, "0");
156	    if (c.id === "typescript") files[`extra-${n}.ts`] = `export const extra${n}: number = ${i};\n`;
157	    else if (c.id === "python") files[`extra-${n}.py`] = `extra${n}: int = ${i}\n`;
158	    else if (c.id === "go") files[`extra-${n}.go`] = `package main\n\nfunc extra${n}() int { return ${i} }\n`;
159	    else {
160	      files[`src/extra_${n}.rs`] = `pub fn extra${n}() -> i32 { ${i} }\n`;
161	      files["src/main.rs"] = `mod extra_${n};\n` + files["src/main.rs"];
162	    }
163	  }
164	  return writeFixture(files);
165	}
166	
167	for (const c of CASES) {
