        // What the server says about the content it is actually given: clean, a little later; with a version, and without.
        "textDocument/didOpen#b.ts": [{ after: 200, ...publish([], "$uri", { version: "$version" }) }],
        "textDocument/didOpen#c.ts": [{ after: 200, ...publish([]) }],
      },
    },
