    await s.close();
  }
});

test("after another open file changed or was deleted, a server that does not publish again leaves the first file unavailable, not its old list", async () => {
  const s = open(
    { on: { "textDocument/didOpen": heldText, "textDocument/didChange#b.ts": heldText, "test/release": [publish([diag(1, "a.ts published again")], "$root/a.ts")] } },
    { "a.ts": "a1", "b.ts": "b1" },
  );
  try {
    assert.deepEqual(await messages(s, "a.ts"), ["a1"]);
    assert.deepEqual(await messages(s, "b.ts"), ["b1"]);

    fs.writeFileSync(path.join(s.ws, "b.ts"), "b2");
    // 300 ms each: the call's own timeout is what ends it.
    assert.deepEqual(await s.mgr.diagnostics("a.ts", 300), superseded("a.ts", 300));
    assert.deepEqual(await s.mgr.diagnostics("a.ts", 300), superseded("a.ts", 300), "asking again does not make the old list current");
    assert.deepEqual(await messages(s, "b.ts"), ["b2"], "the changed file itself has its fresh answer");
    // Through the tool the same state is an error that says so (its 5000 ms timeout is not waited for here: the list arrives).
    const waiting = s.tool("lsp_diagnostics", { path: "a.ts" });
    await (await s.client()).sendRequest("test/release", {});
    assert.equal((await waiting).success, true);
